/// <summary>
/// MPJ_28155_SalesFinalisation 3.6.1 Sales order shipment workbench
/// Copied from AccountingSourceExplorerParameters
/// </summary>
[Form]
public class METSalesOrderShipmentWorkbenchParameters extends FormRun
{
    METSalesOrderShipmentWorkbenchFilterParameters   salesOrderShipmentWorkbenchFilterParameters;

}

    /// <summary>
    /// When user click Ok button
    /// </summary>
    public void closeOk()
    {
        FormRun             callingFormRun;
        METIFormRefresh     callingForm;
        boolean             isValid = true;
        InventLocationId    localInventLocationId = InventLocationId.valueStr();
        SalesShippingDate   localShipDateFrom = ShipDateFrom.dateValue();
        SalesShippingDate   localShipDateTo = ShipDateTo.dateValue();

        // Validate parameters
        if (!localInventLocationId)
        {
            isValid = checkFailed("@MET:WarehouseRequiredWarning");
        }

        if (!localShipDateFrom)
        {
            isValid = checkFailed("@MET:FromShipDateRequiredWarning");
        }

        if (!localShipDateTo)
        {
            isValid = checkFailed("@MET:ToShipDateRequiredWarning");
        }

        if (isValid && (localShipDateFrom > localShipDateTo))
        {
            isValid = checkFailed(strfmt("@SYS55013",
                date2StrUsr(localShipDateFrom, DateFlags::FormatAll),
                date2StrUsr(localShipDateTo, DateFlags::FormatAll)));
        }

        if (isValid)
        {
            // Only save the parameters when valid, so on reopen the parameters match what is displayed in the form
            salesOrderShipmentWorkbenchFilterParameters.parmInventLocationId(localInventLocationId);
            salesOrderShipmentWorkbenchFilterParameters.parmShipDateFrom(localShipDateFrom);
            salesOrderShipmentWorkbenchFilterParameters.parmShipDateTo(localShipDateTo);
            salesOrderShipmentWorkbenchFilterParameters.parmPrimaryRoute(PrimaryRoute.valueStr());
            salesOrderShipmentWorkbenchFilterParameters.parmCustAccount(CustAccount.valueStr());
            salesOrderShipmentWorkbenchFilterParameters.saveLastValue(formStr(METSalesOrderShipmentWorkbenchParameters));

            // refresh the workbench form
            callingFormRun = this.args().caller() as FormRun;
            if (callingFormRun != null && formHasMethod(callingFormRun, identifierStr(refresh)))
            {
                callingForm = callingFormRun as METIFormRefresh;
                callingForm.refresh();
            }

            super();
        }
    }

    /// <summary>
    /// Init method
    /// </summary>
    public void init()
    {
        Object caller;
        FormRun callerForm;

        super();

        caller = this.args().caller();
        callerForm = caller as FormRun;

        if (salesOrderShipmentWorkbenchFilterParameters == null)
        {
            salesOrderShipmentWorkbenchFilterParameters = METSalesOrderShipmentWorkbenchFilterParameters::construct();
            salesOrderShipmentWorkbenchFilterParameters.loadLastValue(formStr(METSalesOrderShipmentWorkbenchParameters));
        }

        // Set dialog fields from salesOrderShipmentWorkbenchFilterParameters class
        InventLocationId.text(salesOrderShipmentWorkbenchFilterParameters.parmInventLocationId());
        ShipDateFrom.dateValue(salesOrderShipmentWorkbenchFilterParameters.parmShipDateFrom());
        ShipDateTo.dateValue(salesOrderShipmentWorkbenchFilterParameters.parmShipDateTo());
        PrimaryRoute.text(salesOrderShipmentWorkbenchFilterParameters.parmPrimaryRoute());
        CustAccount.text(salesOrderShipmentWorkbenchFilterParameters.parmCustAccount());
    }
